package main

import (
	"encoding/json"
	"net/http/httptest"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// /api/filediff shows a changed generated file's diff for the Save dialog — and only that: a file that is not in the list
// of hemma's changed files is 404 (it is not a way to read the repo), and a "new file" that is a symlink is never read.
func TestFileDiff(t *testing.T) {
	dir := t.TempDir()
	s := &server{repo: dir}
	write := func(rel, body string) {
		p := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
		s.invalidateChanges()
	}
	write("services.yaml", "services: {}\n")
	write("edge/caddy/data/sites/demo.caddy", "# GENERATED by hemma — do not edit\nimport auth\n")
	write("hemma-manifest.yaml", "demo:\n    - edge/caddy/data/sites/demo.caddy\n")
	for _, a := range [][]string{{"init", "-q", "-b", "main"}, {"add", "-A"}, {"commit", "-q", "-m", "init"}} {
		if out, err := s.git(time.Minute, a...); err != nil {
			t.Fatalf("git %v: %v %s", a, err, out)
		}
	}
	write("edge/caddy/data/sites/demo.caddy", "# GENERATED by hemma — do not edit\nroute @hemma_outside {\n\timport auth\n}\n")
	write("edge/caddy/data/sites/new.caddy", "# GENERATED by hemma — do not edit\nnew site\n")
	write("notes.txt", "secret-ish\n") // not hemma's
	if err := os.Symlink("/etc/hosts", filepath.Join(dir, "edge/caddy/data/sites/link.caddy")); err != nil {
		t.Fatal(err)
	}
	write("hemma-manifest.yaml", "demo:\n    - edge/caddy/data/sites/demo.caddy\nnew:\n    - edge/caddy/data/sites/new.caddy\nlink:\n    - edge/caddy/data/sites/link.caddy\n")

	get := func(path string) (int, map[string]any) {
		rec := httptest.NewRecorder()
		s.handleFileDiff(rec, httptest.NewRequest("GET", "/api/filediff?path="+url.QueryEscape(path), nil))
		var out map[string]any
		json.Unmarshal(rec.Body.Bytes(), &out)
		return rec.Code, out
	}
	if code, out := get("edge/caddy/data/sites/demo.caddy"); code != 200 || !strings.Contains(out["diff"].(string), "-import auth") || !strings.Contains(out["diff"].(string), "+route @hemma_outside {") {
		t.Errorf("changed file: %d %v", code, out)
	}
	if code, out := get("edge/caddy/data/sites/new.caddy"); code != 200 || !strings.Contains(out["diff"].(string), "+new site") {
		t.Errorf("new file: %d %v", code, out)
	}
	for _, p := range []string{"notes.txt", "../etc/passwd", "", "edge/caddy/data/sites/link.caddy"} {
		if code, out := get(p); code != 404 {
			t.Errorf("%q must be refused, got %d %v", p, code, out)
		}
	}
}
